// CODEGEN: gctrace template.py (traces of an instrumented PUC build)
//! What PUC's `luaL_openlibs` allocates, in order, for each dialect and
//! pointer width, recorded from PUC itself: `[op, x, y]` triples, op 0 a
//! new object or block (tag, size) that stays, 4 one that is garbage once
//! the libraries are open, 1 a resize (old, new), 2 a free (size), 3 the
//! string the previous op made (index into the strings); when the
//! collector ran meanwhile (5.3), 5 a new object freed before the end,
//! 7 the free of such a string, 8 and 9 a step's start and end (for
//! the trace) and, after the last step when it ended in the pause, 6
//! the pace (debt, estimate; 5.1 the threshold, estimate, and 10 its
//! dept). The `H`
//! records are an embedder's opening (`luaL_newstate` then
//! `luaL_openlibs`), the collector running.

